// Static and build checks for the cross-browser extension. Runs with plain
// Node and no dependencies:
//
//   npm test
//
// The checks cover both manifests (generated by build.mjs), the icon PNGs,
// version consistency, the permission set, the security invariants (no direct
// browser-namespace access outside src/browser.js, no localStorage, the token
// only in the Authorization header), the popup/options element ids, and a full
// plain build of both targets into a temporary directory (output layout, the
// store size budget, deterministic ZIP bytes, and ZIP integrity). It never
// launches a browser; README.md documents the manual browser checklists.

import { execFileSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { mkdtemp, readFile, readdir, rm, stat } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateRawSync } from 'node:zlib';

import { EXTENSION_VERSION } from '../src/version.js';
import {
  ICON_SIZES,
  MAX_UNPACKED_BYTES,
  MAX_ZIP_BYTES,
  OPTIONAL_HOST_PERMISSIONS,
  REQUIRED_PERMISSIONS,
  buildManifest,
  crc32,
  makeZip,
  parseArgs,
  pngSize,
  validateManifest,
} from '../build.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const SKIP_DIRS = new Set(['node_modules', 'dist']);
const SKIP_FILES = new Set(['test/check.mjs']);

let failures = 0;

/** @param {string} name @param {unknown} actual @param {unknown} expected */
function check(name, actual, expected) {
  const pass = JSON.stringify(actual) === JSON.stringify(expected);
  if (!pass) {
    failures += 1;
    console.error(`not ok - ${name}\n  expected: ${JSON.stringify(expected)}\n  actual:   ${JSON.stringify(actual)}`);
  } else {
    console.log(`ok - ${name}`);
  }
}

/** @param {string} name @param {boolean} condition */
function checkTruthy(name, condition) {
  if (!condition) {
    failures += 1;
    console.error(`not ok - ${name}`);
  } else {
    console.log(`ok - ${name}`);
  }
}

/** @param {string} name @param {() => unknown} run */
function checkThrows(name, run) {
  let threw = false;
  let message = '';
  try {
    run();
  } catch (error) {
    threw = true;
    message = error instanceof Error ? error.message : String(error);
  }
  if (!threw) {
    failures += 1;
    console.error(`not ok - ${name} (did not throw)`);
  } else {
    console.log(`ok - ${name} (${message})`);
  }
}

/** @param {string} file */
async function readText(file) {
  return readFile(join(root, file), 'utf8');
}

/**
 * Discovery-based file walk, returned as root-relative POSIX paths sorted.
 * @param {string} directory
 * @param {string} [prefix]
 * @returns {Promise<string[]>}
 */
async function walkFiles(directory, prefix = '') {
  const entries = await readdir(directory, { withFileTypes: true });
  const files = [];
  for (const entry of entries.sort((left, right) => (left.name < right.name ? -1 : 1))) {
    const relativeName = prefix ? prefix + '/' + entry.name : entry.name;
    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue;
      files.push(...(await walkFiles(join(directory, entry.name), relativeName)));
    } else {
      files.push(relativeName);
    }
  }
  return files;
}

/** @param {string} buffer @param {number} offset @param {number} length */
function centralName(buffer, offset, length) {
  return buffer.toString('utf8', offset, offset + length);
}

/**
 * Parse and verify a ZIP archive: every central-directory entry is inflated
 * and checked against its recorded CRC-32 and sizes. This is the same
 * dependency-free integrity check `unzip -t` performs.
 * @param {Buffer} input
 * @returns {Array<{name: string, size: number}>}
 */
function readZip(input) {
  const data = Buffer.isBuffer(input) ? input : Buffer.from(input);
  let eocd = -1;
  const stop = Math.max(0, data.length - 22 - 0xffff);
  for (let offset = data.length - 22; offset >= stop; offset -= 1) {
    if (data.length >= offset + 22 && data.readUInt32LE(offset) === 0x06054b50) {
      eocd = offset;
      break;
    }
  }
  if (eocd < 0) throw new Error('ZIP end-of-central-directory record not found');
  const count = data.readUInt16LE(eocd + 10);
  const centralOffset = data.readUInt32LE(eocd + 16);
  const entries = [];
  let offset = centralOffset;
  for (let index = 0; index < count; index += 1) {
    if (data.readUInt32LE(offset) !== 0x02014b50) throw new Error('bad central directory header at ' + offset);
    const method = data.readUInt16LE(offset + 10);
    const checksum = data.readUInt32LE(offset + 16);
    const compressedSize = data.readUInt32LE(offset + 20);
    const uncompressedSize = data.readUInt32LE(offset + 24);
    const nameLength = data.readUInt16LE(offset + 28);
    const extraLength = data.readUInt16LE(offset + 30);
    const commentLength = data.readUInt16LE(offset + 32);
    const localOffset = data.readUInt32LE(offset + 42);
    const name = centralName(data, offset + 46, nameLength);
    if (data.readUInt32LE(localOffset) !== 0x04034b50) throw new Error('bad local header for ' + name);
    const localNameLength = data.readUInt16LE(localOffset + 26);
    const localExtraLength = data.readUInt16LE(localOffset + 28);
    const start = localOffset + 30 + localNameLength + localExtraLength;
    const compressed = data.subarray(start, start + compressedSize);
    const raw = method === 0 ? compressed : method === 8 ? inflateRawSync(compressed) : null;
    if (!raw) throw new Error('unsupported ZIP compression method for ' + name);
    if (raw.length !== uncompressedSize) throw new Error('ZIP size mismatch for ' + name);
    if (crc32(raw) !== checksum) throw new Error('ZIP CRC mismatch for ' + name);
    entries.push({ name, size: uncompressedSize });
    offset += 46 + nameLength + extraLength + commentLength;
  }
  return entries;
}

/** @param {string} label @param {string[]} args */
function runBuild(label, args) {
  const output = execFileSync(process.execPath, [join(root, 'build.mjs'), ...args], {
    cwd: root,
    stdio: ['ignore', 'pipe', 'pipe'],
  }).toString();
  return { label, output };
}

/** @param {string} directory @param {string} file */
async function fileSize(directory, file) {
  return (await stat(join(directory, file))).size;
}

/** @param {string} command @param {string[]} args @returns {boolean} */
function hasCommand(command, args = ['--version']) {
  try {
    execFileSync(command, args, { stdio: 'ignore' });
    return true;
  } catch (error) {
    return Boolean(error && error.code && error.code !== 'ENOENT');
  }
}

async function main() {
  // ------------------------------------------------------------- discovery
  const files = await walkFiles(root);
  const jsFiles = files.filter((file) => (file.endsWith('.js') || file.endsWith('.mjs')) && !SKIP_FILES.has(file));
  checkTruthy('discovers the extension JavaScript files', jsFiles.length >= 16);
  for (const file of jsFiles) {
    try {
      execFileSync(process.execPath, ['--check', join(root, file)], { stdio: 'pipe' });
      console.log('ok - node --check ' + file);
    } catch (error) {
      failures += 1;
      const detail = error && error.stderr ? String(error.stderr) : String(error);
      console.error('not ok - node --check ' + file + '\n' + detail);
    }
  }
  for (const required of [
    'src/browser.js',
    'src/status.js',
    'src/consent.js',
    'src/config.js',
    'src/api.js',
    'src/version.js',
    'background.js',
    'popup.js',
    'options.js',
    'manifest.firefox.json',
  ]) {
    checkTruthy(required + ' exists', files.includes(required));
  }

  // ------------------------------------------------------ versions + package
  const manifest = JSON.parse(await readText('manifest.json'));
  const firefoxOverlay = JSON.parse(await readText('manifest.firefox.json'));
  const pkg = JSON.parse(await readText('package.json'));
  const lock = JSON.parse(await readText('package-lock.json'));
  check('extension version is 0.2.0', EXTENSION_VERSION, '0.2.0');
  check('manifest.json version matches src/version.js', manifest.version, EXTENSION_VERSION);
  check('package.json version matches src/version.js', pkg.version, EXTENSION_VERSION);
  check('package-lock version matches src/version.js', lock.version, EXTENSION_VERSION);
  check('package-lock root package version matches', lock.packages && lock.packages[''] && lock.packages[''].version, EXTENSION_VERSION);
  checkTruthy('version.js declares the extension version', (await readText('src/version.js')).includes("EXTENSION_VERSION = '" + EXTENSION_VERSION + "'"));
  check('the extension has no runtime dependencies', pkg.dependencies, undefined);
  checkTruthy('package.json has the documented scripts', ['build', 'build:chrome', 'build:firefox', 'build:defuddle', 'test'].every((script) => typeof (pkg.scripts || {})[script] === 'string'));
  for (const testFile of [
    'test/check.mjs',
    'test/status.mjs',
    'test/lookup.mjs',
    'test/background.mjs',
    'test/idempotency.mjs',
  ]) {
    checkTruthy('npm test runs ' + testFile, String(pkg.scripts.test).includes(testFile));
  }
  // The background logic test replaces the unavailable full-browser smoke: it
  // must fake the WebExtension namespace before importing background.js and
  // must never launch a browser.
  const backgroundTest = await readText('test/background.mjs');
  checkTruthy(
    'the background test is browser-free',
    !/playwright|puppeteer|chrome-launcher|selenium/i.test(backgroundTest),
  );
  checkTruthy(
    'the background test installs a fake extension namespace before importing',
    backgroundTest.includes('globalThis.chrome') &&
      backgroundTest.includes('globalThis.browser') &&
      backgroundTest.includes('background-test=') &&
      /await loadBackground\(/.test(backgroundTest),
  );
  for (const type of ['eza:pageStatus', 'eza:addBookmark', 'eza:addPage']) {
    checkTruthy('the background test drives ' + type, backgroundTest.includes(type));
  }
  checkTruthy(
    'the background test covers quick-save, clip idempotency, and the token rule',
    backgroundTest.includes('/api/v1/quick-save') &&
      backgroundTest.includes('/api/v1/clip') &&
      backgroundTest.includes('Idempotency-Key') &&
      backgroundTest.includes('token never appears in a request URL'),
  );
  checkTruthy('options page renders the version from src/version.js', /import\s*{[^}]*EXTENSION_VERSION[^}]*}\s*from\s*'\.\/src\/version\.js'/.test(await readText('options.js')) && /EXTENSION_VERSION/.test(await readText('options.js')));
  checkTruthy('popup renders the version from src/version.js', /EXTENSION_VERSION/.test(await readText('popup.js')));

  // ---------------------------------------------------------------- icons
  for (const size of ICON_SIZES) {
    const iconPath = 'icons/icon-' + size + '.png';
    checkTruthy(iconPath + ' exists', existsSync(join(root, iconPath)));
    const dimensions = pngSize(await readFile(join(root, iconPath)));
    check('icon-' + size + '.png dimensions', dimensions, { width: Number(size), height: Number(size) });
  }
  check('manifest icons cover 16/32/48/128', Object.keys(manifest.icons || {}).sort(), ['128', '16', '32', '48']);
  check('action default icon covers 16/32/48/128', Object.keys((manifest.action || {}).default_icon || {}).sort(), ['128', '16', '32', '48']);

  // ------------------------------------------------------- built manifests
  const source = { chrome: manifest, firefox: firefoxOverlay };
  const chromeManifest = buildManifest('chrome', { ...source, version: EXTENSION_VERSION });
  const firefoxManifest = buildManifest('firefox', { ...source, version: EXTENSION_VERSION });
  checkTruthy('Chrome manifest validates', validateManifest(chromeManifest, { target: 'chrome', version: EXTENSION_VERSION }));
  checkTruthy('Firefox manifest validates', validateManifest(firefoxManifest, { target: 'firefox', version: EXTENSION_VERSION }));
  check('Chrome keeps a service-worker background', chromeManifest.background, { service_worker: 'background.js', type: 'module' });
  check('Chrome requires 116 or newer', chromeManifest.minimum_chrome_version, '116');
  check('Chrome has no browser_specific_settings', chromeManifest.browser_specific_settings, undefined);
  checkTruthy('Chrome manifest never gains gecko keys', !JSON.stringify(chromeManifest).includes('gecko'));
  check('Chrome permissions', chromeManifest.permissions, REQUIRED_PERMISSIONS);
  check('Chrome optional host permissions', chromeManifest.optional_host_permissions, OPTIONAL_HOST_PERMISSIONS);
  check('Chrome store build has no static host permission', chromeManifest.host_permissions, undefined);
  check('Chrome has no content scripts', chromeManifest.content_scripts, undefined);
  check('short_name store metadata', chromeManifest.short_name, 'eza clipper');
  check('homepage_url store metadata', chromeManifest.homepage_url, 'https://github.com/meillaya/eza');
  check('action title', chromeManifest.action.default_title, 'eza — add bookmark');
  check('action popup', chromeManifest.action.default_popup, 'popup.html');
  check('options page', chromeManifest.options_page, 'options.html');
  check('commands', Object.keys(chromeManifest.commands).sort(), ['add-bookmark', 'add-selection']);

  check('Firefox has no minimum_chrome_version', firefoxManifest.minimum_chrome_version, undefined);
  check('Firefox uses an event-page background', firefoxManifest.background, { scripts: ['background.js'], type: 'module' });
  check('Firefox add-on id', firefoxManifest.browser_specific_settings.gecko.id, 'eza-clipper@eza.dev');
  check('Firefox minimum version', firefoxManifest.browser_specific_settings.gecko.strict_min_version, '140.0');
  check('Firefox required data collection', firefoxManifest.browser_specific_settings.gecko.data_collection_permissions.required, ['browsingActivity', 'bookmarksInfo']);
  check('Firefox optional data collection', firefoxManifest.browser_specific_settings.gecko.data_collection_permissions.optional, ['websiteContent']);
  checkTruthy('Firefox manifest never gains Chrome-only keys', !JSON.stringify(firefoxManifest).includes('minimum_chrome_version'));
  // short_name and homepage_url are valid WebExtension keys in both browsers;
  // they are store metadata, not Chrome-only fields.
  check('Firefox keeps the store short_name', firefoxManifest.short_name, 'eza clipper');
  check('Firefox keeps the store homepage_url', firefoxManifest.homepage_url, 'https://github.com/meillaya/eza');

  // Validation must reject the mistakes that break a store package.
  checkThrows('a version mismatch is rejected', () => validateManifest(chromeManifest, { target: 'chrome', version: '9.9.9' }));
  checkThrows('a Chrome build with gecko settings is rejected', () =>
    validateManifest({ ...chromeManifest, browser_specific_settings: { gecko: {} } }, { target: 'chrome', version: EXTENSION_VERSION }),
  );
  checkThrows('a Firefox build with minimum_chrome_version is rejected', () =>
    validateManifest({ ...firefoxManifest, minimum_chrome_version: '116' }, { target: 'firefox', version: EXTENSION_VERSION }),
  );
  checkThrows('a missing permission is rejected', () =>
    validateManifest({ ...chromeManifest, permissions: ['activeTab', 'scripting', 'storage'] }, { target: 'chrome', version: EXTENSION_VERSION }),
  );
  checkThrows('a static host permission in the store build is rejected', () =>
    validateManifest({ ...chromeManifest, host_permissions: ['https://example.press/*'] }, { target: 'chrome', version: EXTENSION_VERSION }),
  );
  checkThrows('a Firefox build without data collection is rejected', () => {
    const tampered = JSON.parse(JSON.stringify(firefoxManifest));
    delete tampered.browser_specific_settings.gecko.data_collection_permissions;
    validateManifest(tampered, { target: 'firefox', version: EXTENSION_VERSION });
  });
  checkThrows('a manifest with an unexpected key is rejected', () =>
    validateManifest({ ...chromeManifest, license: 'Apache-2.0' }, { target: 'chrome', version: EXTENSION_VERSION }),
  );

  // The E2E test build bakes the test server origin in as a static host
  // permission so the browser test does not depend on a permission prompt.
  const e2eManifest = buildManifest('chrome', {
    ...source,
    version: EXTENSION_VERSION,
    hostPermission: 'http://127.0.0.1:8000/*',
  });
  check('E2E build host permission', e2eManifest.host_permissions, ['http://127.0.0.1:8000/*']);
  checkTruthy('E2E build manifest validates', validateManifest(e2eManifest, { target: 'chrome', version: EXTENSION_VERSION, hostPermission: 'http://127.0.0.1:8000/*' }));
  check('parseArgs defaults to all targets', parseArgs([]).target, 'all');
  check('parseArgs accepts one target', parseArgs(['--target', 'firefox']).target, 'firefox');
  check('parseArgs accepts an out directory', parseArgs(['--out', 'extension/dist']).out, 'extension/dist');
  check('parseArgs accepts the E2E host permission', parseArgs(['--host-permission', 'http://127.0.0.1:8000/*']).hostPermission, 'http://127.0.0.1:8000/*');
  checkThrows('parseArgs rejects an unknown argument', () => parseArgs(['--nope']));
  checkThrows('parseArgs rejects a bad host permission', () => parseArgs(['--host-permission', 'example.com']));
  check('ZIP writer is deterministic', makeZip([{ name: 'b.txt', data: 'b' }, { name: 'a.txt', data: 'a' }]).equals(makeZip([{ name: 'a.txt', data: 'a' }, { name: 'b.txt', data: 'b' }])), true);
  checkThrows('ZIP writer rejects duplicates', () => makeZip([{ name: 'a', data: 'a' }, { name: 'a', data: 'b' }]));
  checkThrows('ZIP writer rejects absolute paths', () => makeZip([{ name: '/a', data: 'a' }]));
  checkThrows('ZIP writer rejects escaping paths', () => makeZip([{ name: '../a', data: 'a' }]));
  check('ZIP writer round-trips entries', readZip(makeZip([{ name: 'manifest.json', data: '{}' }, { name: 'icons/icon-16.png', data: 'x' }])).map((entry) => entry.name), ['icons/icon-16.png', 'manifest.json']);

  // ---------------------------------------------------- static invariants
  const runtimeSources = [
    'background.js',
    'popup.js',
    'options.js',
    'src/api.js',
    'src/browser.js',
    'src/config.js',
    'src/consent.js',
    'src/extract.js',
    'src/status.js',
    'src/version.js',
  ];
  const runtimeText = {};
  for (const file of runtimeSources) runtimeText[file] = await readText(file);
  const allRuntime = Object.entries(runtimeText)
    .map(([file, text]) => file + '\n' + text)
    .join('\n');
  // Every WebExtension API must go through the src/browser.js shim; even a
  // comment that spells the namespace out would be a wrong example to copy.
  const directNamespace = /\bchrome\s*\./;
  for (const file of runtimeSources) {
    if (file === 'src/browser.js') continue;
    const lines = runtimeText[file].split('\n');
    const offenders = lines
      .map((line, index) => ({ line, index }))
      .filter((entry) => directNamespace.test(entry.line))
      .map((entry) => file + ':' + (entry.index + 1));
    checkTruthy('no direct namespace access in ' + file, offenders.length === 0);
    if (offenders.length) console.error('  offenders: ' + offenders.join(', '));
  }
  checkTruthy('browser.js exposes getApi', /export\s+function\s+getApi\s*\(/.test(runtimeText['src/browser.js']));
  checkTruthy('browser.js prefers the browser namespace', /browser\b/.test(runtimeText['src/browser.js']) && /chrome\b/.test(runtimeText['src/browser.js']));

  checkTruthy('no localStorage anywhere', !/localStorage/.test(allRuntime));
  checkTruthy('no content script file', !files.some((file) => /content[_-]?script/i.test(file)));
  const htmlSources = [await readText('popup.html'), await readText('options.html')];
  checkTruthy('no remote scripts in the extension pages', htmlSources.every((html) => !/<script[^>]+src="(?:https?:)?\/\//.test(html)));
  checkTruthy('no all_urls permission', !JSON.stringify(manifest).includes('all_urls'));

  // Token handling: header only, no cookies, no URL query value, never logged.
  checkTruthy('api.js sends the bearer token in a header', /Authorization:\s*'Bearer '\s*\+\s*config\.captureToken/.test(runtimeText['src/api.js']));
  checkTruthy('api.js omits cookies', /credentials:\s*'omit'/.test(runtimeText['src/api.js']));
  checkTruthy(
    'the lookup encodes the page URL',
    /LOOKUP_PATH = '\/api\/v1\/bookmarks\/lookup'/.test(runtimeText['src/api.js']) &&
      /LOOKUP_PATH \+ '\?url=' \+ encodeURIComponent\(/.test(runtimeText['src/api.js']),
  );
  checkTruthy('no token query parameter', !/[?&](?:token|access_token|key)=/.test(allRuntime));
  checkTruthy('no token in a created tab URL', !/tabs\.create\([^)]*captureToken/.test(allRuntime));
  checkTruthy('no console logging of requests or secrets', !/console\.(log|debug|info)\(/.test(allRuntime));
  checkTruthy('no version 0.1.0 left in the runtime sources', ![...Object.values(runtimeText), ...htmlSources].some((text) => text.includes('0.1.0')));

  // Message and state contract.
  for (const type of ['eza:pageStatus', 'eza:addBookmark', 'eza:addPage', 'eza:extract']) {
    checkTruthy('background implements ' + type, runtimeText['background.js'].includes(type));
  }
  checkTruthy('the popup asks for page status', runtimeText['popup.js'].includes('eza:pageStatus'));
  checkTruthy('the popup can add a bookmark', runtimeText['popup.js'].includes('eza:addBookmark'));
  checkTruthy('the popup can add page text', runtimeText['popup.js'].includes('eza:addPage'));
  checkTruthy('opening the popup never calls eza:extract', !runtimeText['popup.js'].includes('eza:extract'));
  checkTruthy('the popup never injects a script', !/scripting\./.test(runtimeText['popup.js']));
  const pageStatusBody = runtimeText['background.js'].slice(
    runtimeText['background.js'].indexOf('async function handlePageStatus'),
    runtimeText['background.js'].indexOf('async function handleAddBookmark'),
  );
  checkTruthy('page status never extracts the page', pageStatusBody.length > 0 && !/extractTab|scripting\./.test(pageStatusBody));
  checkTruthy('the popup status request is an explicit on-demand check', /interactive:\s*true/.test(pageStatusBody) && /!config\.checkActivePage && !options\.interactive/.test(runtimeText['background.js']));
  const addPageBody = runtimeText['background.js'].slice(
    runtimeText['background.js'].indexOf('async function addPageText'),
    runtimeText['background.js'].indexOf('async function runUserAction'),
  );
  checkTruthy('page text is extracted only inside the add-page action', /extractTab\(/.test(addPageBody));
  checkTruthy('add page text checks Firefox consent', /ensurePageTextConsent/.test(addPageBody));
  checkTruthy('consent reads data_collection', /data_collection/.test(runtimeText['src/consent.js']) && /permissions\.getAll\(\)/.test(runtimeText['src/consent.js']));
  checkTruthy('consent requests websiteContent', /permissions\.request\(\{\s*data_collection:\s*\[WEBSITE_CONTENT\]/.test(runtimeText['src/consent.js']));
  checkTruthy('the status helper has the documented tooltips', /'eza — add bookmark'/.test(runtimeText['src/status.js']) && /'eza — in your library'/.test(runtimeText['src/status.js']) && /'eza — this page cannot be bookmarked'/.test(runtimeText['src/status.js']));
  checkTruthy('the status helper has the badge colours', /#1f6f43/.test(runtimeText['src/status.js']) && /#8a2b20/.test(runtimeText['src/status.js']) && /'✓'/.test(runtimeText['src/status.js']));
  checkTruthy('the lookup failure path marks unsupported servers', /kind:\s*'unsupported'/.test(runtimeText['background.js']) && /lookupUnsupported/.test(runtimeText['background.js']));
  checkTruthy('token errors are cooled down, not retried per page', /authFailure/.test(runtimeText['background.js']) && /LOOKUP_AUTH_COOLDOWN_MS/.test(runtimeText['background.js']));
  checkTruthy('context menus use the documented labels', /'Add bookmark to eza'/.test(runtimeText['background.js']) && /'Add page text to eza'/.test(runtimeText['background.js']) && /'Add selection to eza'/.test(runtimeText['background.js']));
  checkTruthy('the status cache TTL is 60 seconds', /CACHE_TTL_MS = 60000/.test(runtimeText['src/status.js']));

  // ------------------------------------------------------------- ids in HTML
  const pagePairs = [
    ['popup.js', 'popup.html'],
    ['options.js', 'options.html'],
  ];
  for (const [script, html] of pagePairs) {
    const js = await readText(script);
    const markup = await readText(html);
    const ids = new Set([...js.matchAll(/getElementById\('([^']+)'\)/g)].map((match) => match[1]));
    for (const id of ids) {
      checkTruthy(script + ' id #' + id + ' exists in ' + html, markup.includes('id="' + id + '"'));
    }
  }
  const popupHtml = await readText('popup.html');
  for (const id of [
    'loading-panel',
    'setup-panel',
    'add-panel',
    'saved-panel',
    'done-panel',
    'error-panel',
    'page-url',
    'title',
    'tags',
    'add-bookmark',
    'add-page-text',
    'saved-title',
    'saved-tags',
    'saved-read',
    'open-in-eza',
    'saved-add-page-text',
    'done-text',
    'error-text',
    'retry',
  ]) {
    checkTruthy('popup.html exposes #' + id, popupHtml.includes('id="' + id + '"'));
  }
  const optionsHtml = await readText('options.html');
  for (const id of [
    'server-url',
    'token',
    'token-state',
    'default-template',
    'check-active-page',
    'save',
    'test',
    'grant',
    'status',
    'account-link',
    'version',
    'app-icon',
    'page-text-section',
    'page-text-grant',
  ]) {
    checkTruthy('options.html exposes #' + id, optionsHtml.includes('id="' + id + '"'));
  }
  const remoteAsset = /<(?:script|link|img)\b[^>]*(?:src|href)="(?:https?:)?\/\//;
  const localOnlyPages = ![await readText('popup.html'), await readText('options.html')].some((html) => remoteAsset.test(html));
  checkTruthy('popup and options load only local assets', localOnlyPages);

  // -------------------------------------------------- README documentation
  const readme = await readText('README.md');
  checkTruthy('README covers Chrome install', /chrome/i.test(readme) && /firefox/i.test(readme));
  checkTruthy('README documents the store package names', readme.includes('eza-clipper-<version>-chrome.zip') && readme.includes('eza-clipper-<version>-firefox.zip'));
  checkTruthy('README documents the Firefox data collection', readme.includes('data_collection_permissions') || readme.includes('data collection'));
  checkTruthy('README documents the manual Firefox checklist', /manual firefox checklist/i.test(readme));

  // ------------------------------------------------------------- full build
  const tempOne = await mkdtemp(join(tmpdir(), 'eza-clipper-check-'));
  const tempTwo = await mkdtemp(join(tmpdir(), 'eza-clipper-check-'));
  try {
    runBuild('first build', ['--target', 'all', '--out', tempOne]);
    runBuild('second build', ['--target', 'all', '--out', tempTwo]);
    const hasUnzip = hasCommand('unzip', ['-v']);
    for (const target of ['chrome', 'firefox']) {
      const directory = join(tempOne, target);
      const builtFiles = (await walkFiles(directory)).sort();
      const builtManifest = JSON.parse(await readFile(join(directory, 'manifest.json'), 'utf8'));
      checkTruthy(target + ' build manifest validates', validateManifest(builtManifest, { target, version: EXTENSION_VERSION }));
      check('built ' + target + ' version', builtManifest.version, EXTENSION_VERSION);
      check('built ' + target + ' short_name', builtManifest.short_name, 'eza clipper');
      check('built ' + target + ' homepage_url', builtManifest.homepage_url, 'https://github.com/meillaya/eza');
      checkTruthy(target + ' build carries the LICENSE', builtFiles.includes('LICENSE'));
      checkTruthy(target + ' build carries background.js', builtFiles.includes('background.js'));
      checkTruthy(target + ' build carries src/browser.js', builtFiles.includes('src/browser.js'));
      checkTruthy(target + ' build omits the Defuddle entry source', !builtFiles.includes('src/defuddle-page.js'));
      checkTruthy(target + ' build has no tests', !builtFiles.some((file) => file.startsWith('test/')));
      checkTruthy(target + ' build has no node_modules', !builtFiles.some((file) => file.startsWith('node_modules/')));
      checkTruthy(target + ' build has no vendor bundle', !builtFiles.some((file) => file.startsWith('vendor/')));
      if (target === 'chrome') {
        check('built Chrome background', builtManifest.background.service_worker, 'background.js');
        check('built Chrome min version', builtManifest.minimum_chrome_version, '116');
        check('built Chrome has no gecko block', builtManifest.browser_specific_settings, undefined);
      } else {
        check('built Firefox background', builtManifest.background.scripts, ['background.js']);
        check('built Firefox has no Chrome min version', builtManifest.minimum_chrome_version, undefined);
        check('built Firefox gecko id', builtManifest.browser_specific_settings.gecko.id, 'eza-clipper@eza.dev');
      }
      let unpackedBytes = 0;
      for (const file of builtFiles) unpackedBytes += await fileSize(directory, file);
      checkTruthy(target + ' unpacked build is under the store budget', unpackedBytes < MAX_UNPACKED_BYTES);
      const zipPath = join(tempOne, 'eza-clipper-' + EXTENSION_VERSION + '-' + target + '.zip');
      checkTruthy(target + ' ZIP exists', existsSync(zipPath));
      const zipData = await readFile(zipPath);
      checkTruthy(target + ' ZIP is under the store budget', zipData.length < MAX_ZIP_BYTES);
      const zipEntries = readZip(zipData);
      check(target + ' ZIP layout matches the directory', zipEntries.map((entry) => entry.name), builtFiles);
      checkTruthy(target + ' ZIP has manifest.json at the archive root', zipEntries.some((entry) => entry.name === 'manifest.json'));
      const secondZip = await readFile(join(tempTwo, 'eza-clipper-' + EXTENSION_VERSION + '-' + target + '.zip'));
      checkTruthy(target + ' ZIP bytes are deterministic', zipData.equals(secondZip));
      if (hasUnzip) {
        try {
          execFileSync('unzip', ['-t', zipPath], { stdio: 'pipe' });
          console.log('ok - ' + target + ' ZIP passes unzip -t');
        } catch (error) {
          failures += 1;
          const detail = error && error.stdout ? String(error.stdout) : String(error);
          console.error('not ok - ' + target + ' ZIP fails unzip -t\n' + detail);
        }
      }
    }
    const names = (await readdir(tempOne)).sort();
    check('build outputs both directory targets and both ZIPs', names, [
      'chrome',
      'eza-clipper-0.2.0-chrome.zip',
      'eza-clipper-0.2.0-firefox.zip',
      'firefox',
    ]);
  } finally {
    await rm(tempOne, { recursive: true, force: true });
    await rm(tempTwo, { recursive: true, force: true });
  }

  if (failures > 0) {
    console.error(`\n${failures} extension check(s) failed`);
    process.exit(1);
  }
  console.log('\nall extension checks passed');
  console.log('next: npm run build (writes extension/dist/chrome and extension/dist/firefox)');
}

main().catch((error) => {
  console.error('extension check crashed: ' + (error instanceof Error ? error.stack : error));
  process.exit(1);
});
